+                      conv_state.stride(1) == 1 &&
+                      conv_state.stride(2) == 3 * dim,
+                  "conv_state must use the SD cache layout");
+  STD_TORCH_CHECK(state.stride(0) >= num_heads * kHeadDim * kHeadDim &&
